-- Minimal contracts for migration tests, not a production baseline.
create role anon;create role authenticated;create role service_role;
create schema auth;create schema private;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb $$;
create table public.profiles(id uuid primary key,role text,active boolean default true);
create function public.current_app_role() returns text language sql stable security definer set search_path='' as $$ select role from public.profiles where id=auth.uid() and active $$;
create table public.pevs(id bigint primary key,name text);
create table public.routes(id bigint primary key,driver_id uuid,status text,total_distance_m numeric,total_duration_s numeric);
create table public.route_stops(id bigint primary key,route_id bigint,pev_id bigint,status text,sequence integer,planned_distance_m numeric,planned_duration_s numeric,unique(route_id,sequence));
create table public.audit_logs(id bigint generated by default as identity primary key,actor_id uuid,action text,entity_type text,entity_id text,summary text,metadata jsonb);
create table public.route_evidences(id bigint primary key,created_by uuid,storage_path text,sharepoint_status text default 'pending',sharepoint_started_at timestamptz,
sharepoint_attempts integer default 0,sharepoint_last_error text,sharepoint_item_id text,sharepoint_url text,sharepoint_path text,sharepoint_sha256 text,
sharepoint_synced_at timestamptz,storage_deleted_at timestamptz);
create function private.update_own_evidence_sync(bigint,text,text,text,text,text,timestamptz,text,timestamptz) returns jsonb language sql as $$ select '{}'::jsonb $$;
create function public.update_own_evidence_sync(p_evidence_id bigint,p_status text default null,p_item_id text default null,p_url text default null,p_path text default null,p_sha256 text default null,p_synced_at timestamptz default null,p_last_error text default null,p_storage_deleted_at timestamptz default null) returns jsonb language sql security invoker set search_path='' as $$ select private.update_own_evidence_sync(p_evidence_id,p_status,p_item_id,p_url,p_path,p_sha256,p_synced_at,p_last_error,p_storage_deleted_at) $$;
grant usage on schema auth,public,private to authenticated,service_role;
grant execute on all functions in schema auth to authenticated,service_role;
grant select,insert,update on all tables in schema public to authenticated;
